-- Healthcare EMR full MySQL import generated from the project Excel dataset
CREATE DATABASE IF NOT EXISTS Healthcare_EMR;
USE Healthcare_EMR;

SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `Patient`;
CREATE TABLE `Patient` (
  `PatientID` INT NOT NULL,
  `FirstName` VARCHAR(255) NULL,
  `LastName` VARCHAR(255) NULL,
  `Gender` VARCHAR(255) NULL,
  `DateOfBirth` DATETIME NULL,
  `Age` INT NULL,
  `BloodType` VARCHAR(255) NULL,
  `PhoneNumber` VARCHAR(255) NULL,
  `AlternatePhoneNumber` VARCHAR(255) NULL,
  `Address` VARCHAR(255) NULL,
  `State` VARCHAR(255) NULL,
  `City` VARCHAR(255) NULL,
  `Country` VARCHAR(255) NULL,
  `InsuranceProvider` VARCHAR(255) NULL,
  `PolicyNumber` VARCHAR(255) NULL,
  `MaritalStatus` VARCHAR(255) NULL,
  `Race` VARCHAR(255) NULL,
  `Ethnicity` VARCHAR(255) NULL,
  `ChronicConditions` VARCHAR(255) NULL,
  `Allergies` VARCHAR(255) NULL,
  `MedicalHistory` VARCHAR(255) NULL,
  `PatientStatus` VARCHAR(255) NULL,
  `RegistrationDate` DATETIME NULL,
  `EmergencyContactName` VARCHAR(255) NULL,
  `EmergencyContactPhone` VARCHAR(255) NULL,
  PRIMARY KEY (`PatientID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `Doctor`;
CREATE TABLE `Doctor` (
  `DoctorID` INT NOT NULL,
  `DoctorName` VARCHAR(255) NULL,
  `Gender` VARCHAR(255) NULL,
  `Specialty` VARCHAR(255) NULL,
  `DepartmentID` INT NULL,
  `YearsOfExperience` INT NULL,
  `HospitalAffiliation` VARCHAR(255) NULL,
  `ClinicName` VARCHAR(255) NULL,
  `PhoneNumber` VARCHAR(255) NULL,
  `Email` VARCHAR(255) NULL,
  `LicenseNumber` VARCHAR(255) NULL,
  `IsActive` VARCHAR(255) NULL,
  PRIMARY KEY (`DoctorID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `Visit`;
CREATE TABLE `Visit` (
  `VisitID` INT NOT NULL,
  `PatientID` INT NULL,
  `DoctorID` INT NULL,
  `VisitDate` DATETIME NULL,
  `VisitYear` INT NULL,
  `VisitMonth` INT NULL,
  `VisitMonthName` VARCHAR(255) NULL,
  `VisitQuarter` INT NULL,
  `VisitType` VARCHAR(255) NULL,
  `VisitStatus` VARCHAR(255) NULL,
  `Diagnosis` VARCHAR(255) NULL,
  `DiagnosisCode` VARCHAR(255) NULL,
  `ReasonForVisit` VARCHAR(255) NULL,
  `FollowUpRequired` VARCHAR(255) NULL,
  `PrescribedMedications` VARCHAR(255) NULL,
  `VisitDurationMins` INT NULL,
  PRIMARY KEY (`VisitID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `Treatment`;
CREATE TABLE `Treatment` (
  `TreatmentID` INT NOT NULL,
  `VisitID` INT NULL,
  `TreatmentType` VARCHAR(255) NULL,
  `TreatmentName` VARCHAR(255) NULL,
  `MedicationPrescribed` VARCHAR(255) NULL,
  `Dosage` VARCHAR(255) NULL,
  `Instructions` VARCHAR(255) NULL,
  `TreatmentStartDate` DATETIME NULL,
  `TreatmentEndDate` DATETIME NULL,
  `DurationDays` INT NULL,
  `Status` VARCHAR(255) NULL,
  `Outcome` VARCHAR(255) NULL,
  `DirectTreatmentCost` DECIMAL(18,4) NULL,
  `TotalEpisodeCost` DECIMAL(18,4) NULL,
  `TreatmentDescription` VARCHAR(255) NULL,
  PRIMARY KEY (`TreatmentID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `LabTest`;
CREATE TABLE `LabTest` (
  `LabResultID` INT NOT NULL,
  `VisitID` INT NULL,
  `OrderedByDoctorID` INT NULL,
  `TestName` VARCHAR(255) NULL,
  `TestDate` DATETIME NULL,
  `TestYear` INT NULL,
  `TestMonth` INT NULL,
  `TestMonthName` VARCHAR(255) NULL,
  `TestResult` VARCHAR(255) NULL,
  `NumericResultValue` DECIMAL(18,4) NULL,
  `Units` VARCHAR(255) NULL,
  `ReferenceRange` VARCHAR(255) NULL,
  `Comments` VARCHAR(255) NULL,
  PRIMARY KEY (`LabResultID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `Department`;
CREATE TABLE `Department` (
  `DepartmentID` INT NOT NULL,
  `DepartmentName` VARCHAR(255) NULL,
  `SpecialtyCovered` VARCHAR(255) NULL,
  `Location` VARCHAR(255) NULL,
  `DepartmentType` VARCHAR(255) NULL,
  PRIMARY KEY (`DepartmentID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `Billing`;
CREATE TABLE `Billing` (
  `BillID` INT NOT NULL,
  `VisitID` INT NULL,
  `PatientID` INT NULL,
  `AmountBilled` DECIMAL(18,4) NULL,
  `InsuranceCovered` DECIMAL(18,4) NULL,
  `PatientPaid` DECIMAL(18,4) NULL,
  `Outstanding` DECIMAL(18,4) NULL,
  `PaymentStatus` VARCHAR(255) NULL,
  `BillDate` DATETIME NULL,
  `PaymentDate` DATETIME NULL,
  PRIMARY KEY (`BillID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `InsuranceProvider`;
CREATE TABLE `InsuranceProvider` (
  `ProviderID` VARCHAR(255) NOT NULL,
  `ProviderName` VARCHAR(255) NULL,
  `TickerSymbol` VARCHAR(255) NULL,
  `PrimaryPlanType` VARCHAR(255) NULL,
  `NetworkScope` VARCHAR(255) NULL,
  `MemberSatisfaction` DECIMAL(18,4) NULL,
  `CustomerServicePhone` VARCHAR(255) NULL,
  `FinancialRating` VARCHAR(255) NULL,
  PRIMARY KEY (`ProviderID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `InsurancePolicy`;
CREATE TABLE `InsurancePolicy` (
  `PolicyNumber` VARCHAR(255) NOT NULL,
  `PatientID` INT NULL,
  `ProviderID` VARCHAR(255) NULL,
  `ProviderName` VARCHAR(255) NULL,
  `PlanType` VARCHAR(255) NULL,
  `CoverageTier` VARCHAR(255) NULL,
  `MonthlyPremium` DECIMAL(18,4) NULL,
  `AnnualDeductible` INT NULL,
  `Copay` INT NULL,
  `OutOfPocketMax` INT NULL,
  `CoinsurancePct` INT NULL,
  `CoverageStartDate` DATETIME NULL,
  `CoverageEndDate` DATETIME NULL,
  `PolicyStatus` VARCHAR(255) NULL,
  `RxCoverage` VARCHAR(255) NULL,
  `MentalHealthCoverage` VARCHAR(255) NULL,
  `DentalRider` VARCHAR(255) NULL,
  `VisionRider` VARCHAR(255) NULL,
  PRIMARY KEY (`PolicyNumber`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DROP TABLE IF EXISTS `InsuranceClaims`;
CREATE TABLE `InsuranceClaims` (
  `ClaimID` VARCHAR(255) NOT NULL,
  `BillID` INT NULL,
  `VisitID` INT NULL,
  `PatientID` INT NULL,
  `PolicyNumber` VARCHAR(255) NULL,
  `ProviderID` VARCHAR(255) NULL,
  `ProviderName` VARCHAR(255) NULL,
  `PlanType` VARCHAR(255) NULL,
  `ClaimType` VARCHAR(255) NULL,
  `ClaimDate` DATETIME NULL,
  `AmountBilled` DECIMAL(18,4) NULL,
  `AmountClaimed` DECIMAL(18,4) NULL,
  `ApprovedAmount` DECIMAL(18,4) NULL,
  `PatientResponsibility` DECIMAL(18,4) NULL,
  `Outstanding` DECIMAL(18,4) NULL,
  `ClaimStatus` VARCHAR(255) NULL,
  `DenialReason` VARCHAR(255) NULL,
  `ProcessingDays` DECIMAL(18,4) NULL,
  `AppealStatus` VARCHAR(255) NULL,
  `SubmittedElectronically` VARCHAR(255) NULL,
  `NetworkStatus` VARCHAR(255) NULL,
  PRIMARY KEY (`ClaimID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

