-- Foreign keys and indexes
ALTER TABLE `Doctor` ADD INDEX `idx_Doctor_DepartmentID` (`DepartmentID`);
ALTER TABLE `Visit` ADD INDEX `idx_Visit_PatientID` (`PatientID`);
ALTER TABLE `Visit` ADD INDEX `idx_Visit_DoctorID` (`DoctorID`);
ALTER TABLE `Treatment` ADD INDEX `idx_Treatment_VisitID` (`VisitID`);
ALTER TABLE `LabTest` ADD INDEX `idx_LabTest_VisitID` (`VisitID`);
ALTER TABLE `LabTest` ADD INDEX `idx_LabTest_OrderedByDoctorID` (`OrderedByDoctorID`);
ALTER TABLE `Billing` ADD INDEX `idx_Billing_VisitID` (`VisitID`);
ALTER TABLE `Billing` ADD INDEX `idx_Billing_PatientID` (`PatientID`);
ALTER TABLE `InsurancePolicy` ADD INDEX `idx_InsurancePolicy_PatientID` (`PatientID`);
ALTER TABLE `InsurancePolicy` ADD INDEX `idx_InsurancePolicy_ProviderID` (`ProviderID`);
ALTER TABLE `InsuranceClaims` ADD INDEX `idx_InsuranceClaims_BillID` (`BillID`);
ALTER TABLE `InsuranceClaims` ADD INDEX `idx_InsuranceClaims_VisitID` (`VisitID`);
ALTER TABLE `InsuranceClaims` ADD INDEX `idx_InsuranceClaims_PatientID` (`PatientID`);
ALTER TABLE `InsuranceClaims` ADD INDEX `idx_InsuranceClaims_PolicyNumber` (`PolicyNumber`);
ALTER TABLE `InsuranceClaims` ADD INDEX `idx_InsuranceClaims_ProviderID` (`ProviderID`);
ALTER TABLE `Doctor` ADD CONSTRAINT `fk_Doctor_DepartmentID` FOREIGN KEY (`DepartmentID`) REFERENCES `Department` (`DepartmentID`);
ALTER TABLE `Visit` ADD CONSTRAINT `fk_Visit_PatientID` FOREIGN KEY (`PatientID`) REFERENCES `Patient` (`PatientID`);
ALTER TABLE `Visit` ADD CONSTRAINT `fk_Visit_DoctorID` FOREIGN KEY (`DoctorID`) REFERENCES `Doctor` (`DoctorID`);
ALTER TABLE `Treatment` ADD CONSTRAINT `fk_Treatment_VisitID` FOREIGN KEY (`VisitID`) REFERENCES `Visit` (`VisitID`);
ALTER TABLE `LabTest` ADD CONSTRAINT `fk_LabTest_VisitID` FOREIGN KEY (`VisitID`) REFERENCES `Visit` (`VisitID`);
ALTER TABLE `LabTest` ADD CONSTRAINT `fk_LabTest_OrderedByDoctorID` FOREIGN KEY (`OrderedByDoctorID`) REFERENCES `Doctor` (`DoctorID`);
ALTER TABLE `Billing` ADD CONSTRAINT `fk_Billing_VisitID` FOREIGN KEY (`VisitID`) REFERENCES `Visit` (`VisitID`);
ALTER TABLE `Billing` ADD CONSTRAINT `fk_Billing_PatientID` FOREIGN KEY (`PatientID`) REFERENCES `Patient` (`PatientID`);
ALTER TABLE `InsurancePolicy` ADD CONSTRAINT `fk_InsurancePolicy_PatientID` FOREIGN KEY (`PatientID`) REFERENCES `Patient` (`PatientID`);
ALTER TABLE `InsurancePolicy` ADD CONSTRAINT `fk_InsurancePolicy_ProviderID` FOREIGN KEY (`ProviderID`) REFERENCES `InsuranceProvider` (`ProviderID`);
ALTER TABLE `InsuranceClaims` ADD CONSTRAINT `fk_InsuranceClaims_BillID` FOREIGN KEY (`BillID`) REFERENCES `Billing` (`BillID`);
ALTER TABLE `InsuranceClaims` ADD CONSTRAINT `fk_InsuranceClaims_VisitID` FOREIGN KEY (`VisitID`) REFERENCES `Visit` (`VisitID`);
ALTER TABLE `InsuranceClaims` ADD CONSTRAINT `fk_InsuranceClaims_PatientID` FOREIGN KEY (`PatientID`) REFERENCES `Patient` (`PatientID`);
ALTER TABLE `InsuranceClaims` ADD CONSTRAINT `fk_InsuranceClaims_PolicyNumber` FOREIGN KEY (`PolicyNumber`) REFERENCES `InsurancePolicy` (`PolicyNumber`);
ALTER TABLE `InsuranceClaims` ADD CONSTRAINT `fk_InsuranceClaims_ProviderID` FOREIGN KEY (`ProviderID`) REFERENCES `InsuranceProvider` (`ProviderID`);

SET FOREIGN_KEY_CHECKS=1;

-- QA row counts
SELECT 'Patient' AS table_name, COUNT(*) AS row_count FROM Patient UNION ALL
SELECT 'Doctor', COUNT(*) FROM Doctor UNION ALL
SELECT 'Department', COUNT(*) FROM Department UNION ALL
SELECT 'Visit', COUNT(*) FROM Visit UNION ALL
SELECT 'Treatment', COUNT(*) FROM Treatment UNION ALL
SELECT 'LabTest', COUNT(*) FROM LabTest UNION ALL
SELECT 'Billing', COUNT(*) FROM Billing UNION ALL
SELECT 'InsuranceProvider', COUNT(*) FROM InsuranceProvider UNION ALL
SELECT 'InsurancePolicy', COUNT(*) FROM InsurancePolicy UNION ALL
SELECT 'InsuranceClaims', COUNT(*) FROM InsuranceClaims;


show tables;

-- aggregate functions 
select*from insuranceclaims;

select sum(amountbilled) from insuranceclaims ;
select sum(approvedamount) from insuranceclaims;
select sum(amountclaimed) from insuranceclaims;
select avg(AmountBilled) from insuranceclaims;
select max(AmountBilled) from insuranceclaims;
select min(AmountBilled) from insuranceclaims;

-- group by(insuranceclaims)

select providerid,sum(amountbilled) from insuranceclaims group by providerid;

-- window function

select providerid, providername,amountbilled,amountclaimed,dense_rank() over(partition by providerid order by amountbilled) as heighest_revenue from insuranceclaims;


-- joins

select*from doctor;
select*from department;

-- if i want all dactorname, specialty , departmenttype, location and is_active in one table (left join)

select d.departmentid, d.doctorname,d.specialty,
p.departmenttype,p.location,d.isactive from doctor d left join department p on d.departmentid=p.departmentid ;


select*from insuranceprovider;
select*from insurancepolicy;

select r.providername,r.tickersymbol,
o.plantype,o.coveragetier,o.monthlypremium,o.annualdeductible from insuranceprovider r inner join insurancepolicy o on r.providerid=o.providerid;


select*from visit;
select*from patient;

select v.patientid ,p.firstname,p.gender,v.visitmonth from visit v right join patient p on v.patientid=p.patientid;

 -- stored procedures

select*from visit; 

call healthcare_emr.patients_visit_history(236037);

 select*from billing;
call healthcare_emr.payments_pending();

select*from patient;

call healthcare_emr.patient_blood_grp('a-');


-- triggers

select*from treatment;

delimiter $$
create trigger before_update_treatment
before update on treatment
for each row
begin
-- if status changes to discontinued, force outcome to failed
if new.status ='discontinued' then
set new.outcome='failed';
end if;
end
delimiter ;
show triggers;
set sql_safe_updates=0;
 update treatment set status='discontinued' where treatmentid=3;
 

-- views

select*from patient;

create view female_patients as
select*from patient where gender='female';
select*from female_patients;
